SELECT percentile_cont(0.9) within GROUP (ORDER BY AVG(labevents.value)) AS percentile FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id WHERE labevents.itemid = 84807002 AND icustays.patient_gender = 'M' AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2018 AND 2019 AND EXTRACT(YEAR FROM age(CURRENT_DATE, icustays.patient_dob)) BETWEEN 81 AND 91 AND labevents.charttime BETWEEN icustays.intime AND (icustays.intime + interval '48 hours');